```javascript
import { 
  Group, 
  Mesh, 
  PlaneGeometry,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DoubleSide
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Dimensions & colors
  const ribbonWidth = 7.0;
  const ribbonHeight = 0.35;
  const fadeWidth = 0.6;
  const tickMarkWidth = 0.02;
  const tickMarkHeight = 0.14;
  const gapSize = 0.5;

  const colors = {
    bg: 0x111117,
    hairline: 0x23232b,
    accent: 0xff2a38,
    stage: 0x0b0b10,
    paper: 0xe8ecf2
  };

  // Text items
  const tickerItems = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18'
  ];

  // Resource tracking
  const geos = [];
  const mats = [];

  // 1. Create ribbon background plane
  const ribbonGeo = new THREE.PlaneGeometry(ribbonWidth, ribbonHeight);
  const ribbonMat = new THREE.MeshStandardNodeMaterial();
  ribbonMat.color.setHex(colors.bg);
  ribbonMat.roughness = 0.6;
  ribbonMat.metalness = 0.2;
  geos.push(ribbonGeo);
  mats.push(ribbonMat);

  const ribbon = new THREE.Mesh(ribbonGeo, ribbonMat);
  ribbon.position.z = -0.01;
  group.add(ribbon);

  // 2. Add top and bottom hairlines
  const hairlineGeo = new THREE.PlaneGeometry(ribbonWidth, 0.006);
  geos.push(hairlineGeo);

  const hairlineMat = new THREE.MeshStandardNodeMaterial();
  hairlineMat.color.setHex(colors.hairline);
  hairlineMat.roughness = 0.6;
  hairlineMat.metalness = 0.2;
  mats.push(hairlineMat);

  const topHairline = new THREE.Mesh(hairlineGeo, hairlineMat);
  topHairline.position.y = ribbonHeight / 2 - 0.003;
  topHairline.position.z = 0.001;
  group.add(topHairline);

  const bottomHairline = new THREE.Mesh(hairlineGeo, hairlineMat.clone());
  bottomHairline.position.y = -ribbonHeight / 2 + 0.003;
  bottomHairline.position.z = 0.001;
  group.add(bottomHairline);
  mats.push(bottomHairline.material);

  // 3. Build content strip (ticker items + accent ticks)
  const contentGroup = new THREE.Group();
  contentGroup.position.z = 0.02;

  let xPos = 0.25;

  for (let i = 0; i < tickerItems.length; i++) {
    // Create text mesh
    const textMesh = ctx.fontAtlas.createText(tickerItems[i], {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left'
    });

    // Estimate text width (JetBrains Mono 700 at 13px ≈ 0.09 units per character)
    const textWidth = tickerItems[i].length * 0.09;
    textMesh.position.x = xPos;
    textMesh.position.y = 0;
    contentGroup.add(textMesh);

    xPos += textWidth + gapSize;

    // Add vertical accent tick mark between items (except after last)
    if (i < tickerItems.length - 1) {
      const tickGeo = new THREE.PlaneGeometry(tickMarkWidth, tickMarkHeight);
      const tickMat = new THREE.MeshBasicNodeMaterial();
      tickMat.color.setHex(colors.accent);
      tickMat.emissive.setHex(colors.accent);
      tickMat.emissiveIntensity = 1.5;
      geos.push(tickGeo);
      mats.push(tickMat);

      const tick = new THREE.Mesh(tickGeo, tickMat);
      tick.position.x = xPos + tickMarkWidth / 2;
      tick.position.y = 0;
      tick.position.z = 0.001;
      contentGroup.add(tick);

      xPos += tickMarkWidth + gapSize;
    }
  }

  xPos += 0.25;
  const stripWidth = xPos;

  // 4. Create looped content group
  const loopedContent = new THREE.Group();
  loopedContent.add(contentGroup);

  const content2 = contentGroup.clone();
  content2.position.x = stripWidth;
  loopedContent.add(content2);

  group.add(loopedContent);

  // 5. Apply fly-through primitive (constant leftward motion, 0.4 units/sec, linear)
  let flyResult = null;
  if (ctx.primitives && ctx.primitives['fly-through']) {
    flyResult = ctx.primitives['fly-through'](loopedContent, {
      speed: 0.4,
      depthUnits: 0
    });
  }

  // 6. Create edge fade planes (dissolve content into stage)
  const fadeMat = new THREE.MeshBasicNodeMaterial();
  fadeMat.color.setHex(colors.stage);
  mats.push(fadeMat);

  const fadePlaneGeo = new THREE.PlaneGeometry(fadeWidth, ribbonHeight);
  geos.push(fadePlaneGeo);

  const leftFade = new THREE.Mesh(fadePlaneGeo, fadeMat.clone());
  leftFade.position.x = -ribbonWidth / 2 + fadeWidth / 2;
  leftFade.position.z = 0.03;
  group.add(leftFade);
  mats.push(leftFade.material);

  const rightFade = new THREE.Mesh(fadePlaneGeo, fadeMat.clone());
  rightFade.position.x = ribbonWidth / 2 - fadeWidth / 2;
  rightFade.position.z = 0.03;
  group.add(rightFade);
  mats.push(rightFade.material);

  // Cleanup function
  group.userData.cleanup = () => {
    // Dispose tracked resources
    geos.forEach(g => g.dispose());
    mats.forEach(m => m.dispose());

    // Traverse and dispose any unmapped resources
    group.traverse((node) => {
      if (node.geometry && !geos.includes(node.geometry)) {
        node.geometry.dispose();
      }
      if (node.material) {
        const matList = Array.isArray(node.material) ? node.material : [node.material];
        matList.forEach(m => {
          if (!mats.includes(m)) m.dispose();
        });
      }
      // Call cleanup on text meshes if available
      if (node.userData?.cleanup && typeof node.userData.cleanup === 'function') {
        node.userData.cleanup();
      }
    });

    // Kill primitives and timelines
    if (flyResult?.cleanup) flyResult.cleanup();
    gsap.killTweensOf(group);
  };

  return group;
}
